verification_commands.ac1:
root=$(git rev-parse --show-toplevel 2>/dev/null) || root=.
cd "$root" || { echo "FAIL AC-1: cannot cd to the repo root"; exit 1; }
[ -f backend/app/main.py ] || { echo "FAIL AC-1: not run from the TableQueue repo root (backend/app/main.py missing)"; exit 1; }
[ -x backend/.venv/Scripts/python.exe ] || { echo "FAIL AC-1: not measured - backend/.venv/Scripts/python.exe is missing (create the suite venv: cd backend && uv sync)"; exit 1; }
mkdir -p backend/.scratch
scratch="backend/.scratch/_t18ac1_$$.db"; srel="${scratch#backend/}"; rm -f "$scratch" "$scratch.out"
( cd backend && env DATABASE_URL="sqlite:///$srel" JWT_SECRET="t18ac1-secret-0123456789-abcdefghijklmnopqrstuvwxyz" STAFF_PIN=0000 ENV=development TZ=UTC .venv/Scripts/python.exe - <<'PY' > "${srel}.out" 2>&1
import logging, sys, warnings
warnings.filterwarnings("ignore")
logging.disable(logging.WARNING)

def shape_problems(resp, want_status):
    if resp.status_code != want_status:
        return ["status is %d, want %d" % (resp.status_code, want_status)]
    try:
        body = resp.json()
    except Exception:
        return ["body is not JSON"]
    if not isinstance(body, dict) or set(body.keys()) != {"error"}:
        return ["top level is %r, want exactly ['error']" % (sorted(body.keys()) if isinstance(body, dict) else type(body).__name__,)]
    err = body["error"]
    if not isinstance(err, dict):
        return ["error is not an object"]
    if "detail" in body or "detail" in err:
        return ["a 'detail' key (framework default shape) leaked through"]
    if not isinstance(err.get("code"), str) or not err["code"]:
        return ["error.code is missing or not a non-empty string"]
    if not isinstance(err.get("message"), str) or not err["message"]:
        return ["error.message is missing or not a non-empty string"]
    if "details" in err and not isinstance(err["details"], dict):
        return ["error.details is present but not an object"]
    return []

from fastapi.testclient import TestClient
from app.main import app

problems = []
with TestClient(app, raise_server_exceptions=False) as c:
    for path in ("/api/v1/definitely-not-a-route", "/api/v1/../../etc/passwd", "/nope"):
        r = c.get(path)
        p = shape_problems(r, 404)
        if p:
            problems.append("GET %s: %s (body=%r)" % (path, "; ".join(p), r.text[:120]))
    r = c.delete("/health")
    p = shape_problems(r, 405)
    if p:
        problems.append("DELETE /health: %s (body=%r)" % ("; ".join(p), r.text[:120]))
if problems:
    for p in problems:
        print("  " + p)
    sys.exit(1)
print("PROBE_OK")
PY
)
rc=$?
if [ $rc -ne 0 ]; then
  cat "$scratch.out"
  echo "FAIL AC-1: router-level 404/405 refusals do not carry the contract error envelope - probe detail above"
  rm -f "$scratch" "$scratch.out"; rmdir backend/.scratch 2>/dev/null; rm -rf backend/.pytest_cache
  exit 1
fi
echo "PASS AC-1: unmatched-path 404 (incl. traversal-style) and 405 method-not-allowed all carry the {error:{code,message}} envelope"
rm -f "$scratch" "$scratch.out"; rmdir backend/.scratch 2>/dev/null; rm -rf backend/.pytest_cache
exit 0
